-- =====================================================================
-- seed_mock_orders.sql
-- Realistic mock order dataset for Food Delivery platform
-- Total Orders: 3000, Total Order Items: 5600
-- Date range: 2026-10-11 to 2026-11-21 (42 days)
-- Safe & Idempotent: deletes previous code LIKE 'MOCK-%' orders.
-- =====================================================================

START TRANSACTION;

-- ---------------------------------------------------------------------
-- 1. Dọn dẹp đơn mock cũ (idempotent: xóa đơn MOCK cũ mà không chạm đơn thật)
--    order_items tự động bị xóa theo nhờ ràng buộc ON DELETE CASCADE
-- ---------------------------------------------------------------------
DELETE FROM orders WHERE code LIKE 'MOCK-%';

-- ---------------------------------------------------------------------
-- 2. Đảm bảo các tài khoản khách hàng mock tồn tại (vai trò CUSTOMER)
-- ---------------------------------------------------------------------
ON DUPLICATE KEY UPDATE status = 'ACTIVE';

-- ---------------------------------------------------------------------
-- 3. Tạo bảng tạm nạp orders (tránh xung đột auto_increment ID)
-- ---------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_mock_orders;
CREATE TEMPORARY TABLE tmp_mock_orders (
    code VARCHAR(20) NOT NULL PRIMARY KEY,
    customer_phone VARCHAR(20) NOT NULL,
    restaurant_name VARCHAR(150) NOT NULL,
    status ENUM('PENDING_PAYMENT','PLACED','ACCEPTED','PREPARING','READY_FOR_PICKUP',
                'PICKED_UP','DELIVERING','DELIVERED','CANCELLED','REJECTED') NOT NULL,
    receiver_name VARCHAR(100) NOT NULL,
    receiver_phone VARCHAR(20) NOT NULL,
    delivery_address VARCHAR(255) NOT NULL,
    delivery_lat DECIMAL(10,7) NOT NULL,
    delivery_lng DECIMAL(11,7) NOT NULL,
    note VARCHAR(255) NULL,
    subtotal DECIMAL(12,0) NOT NULL,
    delivery_fee DECIMAL(12,0) NOT NULL DEFAULT 0,
    discount_amount DECIMAL(12,0) NOT NULL DEFAULT 0,
    total_amount DECIMAL(12,0) NOT NULL,
    payment_method ENUM('COD','VNPAY','MOMO') NOT NULL DEFAULT 'COD',
    distance_km DECIMAL(6,2) NULL,
    estimated_minutes SMALLINT UNSIGNED NULL,
    cancel_reason VARCHAR(255) NULL,
    created_at DATETIME NOT NULL,
    accepted_at DATETIME NULL,
    delivered_at DATETIME NULL,
    cancelled_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

